urlset:
{% for post in posts %}

  {{ post.permalink | uriencode }}
  {% if post.lastupdate %}
  {% if post.lastupdate.toISOString %}
  {{ post.lastupdate | formatDate }}
  {% else %}
  {{ post.lastupdate }}
  {% endif %}
  {% elif post.updated %}
  {{ post.updated.clone().tz(config.timezone).format() }}
  {% elif post.date %}
  {{ post.date.clone().tz(config.timezone).format() }}
  {% endif %}

{% endfor %}

  {{ config.url | uriencode }}
  {{ sNow.toISOString() }}

{% for tag in tags %}

  {{ tag.permalink | uriencode }}

{% endfor %}
{% for category in categories %}

  {{ category.permalink | uriencode }}

{% endfor %}
